    async def _items(self) -> AsyncIterator[OrderOrderCartGenericProductDefinition]:
        for data in await self._session.api(_OrderV1API).list_cart_cloud_db(
            cart_id=_required(self._scope, "cartId"),
            **{k: v for k, v in self._criteria.items() if k not in {"_"}},
        ):
            yield data

    async def create(
        self,
        *,
        body: OrderCartGenericProductCreation,
    ) -> Item:
        """
        POST /1.0/order/cart/{cartId}/cloudDB

        Add a cloudDB in your cart
        """
        return Item._from(
            self._session,
            self._scope,
            await self._session.api(_OrderV1API).create_cart_cloud_db(
                cart_id=_required(self._scope, "cartId"), body=body
            ),
        )


