class Apc(_OrderV1OrderOrder, ApcRef):
    """A apc, loaded."""

    @classmethod
    def _from(cls, session: _Session, scope: _Key, data: _OrderV1OrderOrder) -> Self:
        ref_key: _Key = {**scope}
        ref_key["duration"] = scope.get("duration") or None
        return _bind(cls, session, data, ref_key)


class ApcCollection(_Collection[Apc]):
    """Every apc: iterate, `filter`, or call with an identifier."""

    def __call__(self, duration: str, /) -> ApcRef:
        ref_key: _Key = {**self._scope, "duration": _identifier(duration)}
        return ApcRef._of(self._session, ref_key)

    async def _items(self) -> AsyncIterator[Apc]:
        listed = await self._session.api(_OrderV1API).list_dedicated_housing_apc(
            service_name=_required(self._scope, "serviceName"),
            **{k: v for k, v in self._criteria.items() if k not in {"_"}},
        )
        scope: _Key = {
            **self._scope,
        }
        refs = [
            ApcRef._of(self._session, {**scope, "duration": str(value)})
            for value in listed
        ]
        async for loaded in _load_each(
            refs, self._session.client.settings.max_concurrency
        ):
            yield loaded

    async def ids(self) -> AsyncIterator[str]:
        """The identifiers only, without loading the objects."""
        for value in await self._session.api(_OrderV1API).list_dedicated_housing_apc(
            service_name=_required(self._scope, "serviceName"),
            **{k: v for k, v in self._criteria.items() if k not in {"_"}},
        ):
            yield str(value)


