class OfferCollection(_Collection[Offer]):
    """Every offer: iterate, `filter`, or call with an identifier."""

    def __call__(self, id: str, /) -> OfferRef:
        ref_key: _Key = {**self._scope, "id": _identifier(id)}
        return OfferRef._of(self._session, ref_key)

    def filter(
        self,
        *,
        merchants: list[CommercialCatalogMerchantEnum] | None = None,
        nature: CommercialCatalogOfferNatureEnum | None = None,
        product_code: str | None = None,
        state: list[CommercialCatalogOfferStateEnum] | None = None,
        technical_requirements: list[str] | None = None,
        type_: CommercialCatalogOfferTypeEnum | None = None,
    ) -> OfferCollection:
        """The same collection, narrowed to the items matching these criteria."""
        return self._narrowed(
            merchants=merchants,
            nature=nature,
            product_code=product_code,
            state=state,
            technical_requirements=technical_requirements,
            type_=type_,
        )

    async def _items(self) -> AsyncIterator[Offer]:
        async for data in self._session.api(_CommercialCatalogV2API).list_offers_iter(
            **{k: v for k, v in self._criteria.items() if k not in {"_"}}
        ):
            yield Offer._from(self._session, self._scope, data)


